class Solution:
    def minimumRefill(self, plants: list[int], capacityA: int, capacityB: int) -> int:
        left = 0
        right = len(plants) - 1
        water_a = capacityA
        water_b = capacityB
        refills = 0

        while left < right:
            if water_a < plants[left]:
                refills += 1
                water_a = capacityA
            water_a -= plants[left]
            left += 1

            if water_b < plants[right]:
                refills += 1
                water_b = capacityB
            water_b -= plants[right]
            right -= 1

        if left == right:
            if max(water_a, water_b) < plants[left]:
                refills += 1

        return refills

#include <vector>
#include <algorithm>

class Solution {
public:
    int minimumRefill(std::vector<int>& plants, int capacityA, int capacityB) {
        int left = 0, right = plants.size() - 1;
        int waterA = capacityA, waterB = capacityB;
        int refills = 0;

        while (left < right) {
            if (waterA < plants[left]) {
                refills++;
                waterA = capacityA;
            }
            waterA -= plants[left++];

            if (waterB < plants[right]) {
                refills++;
                waterB = capacityB;
            }
            waterB -= plants[right--];
        }

        if (left == right) {
            if (std::max(waterA, waterB) < plants[left]) {
                refills++;
            }
        }
        return refills;
    }
};

